// place a tower only if it does not cut the spawn off from the exit
bool TryPlaceTower(int[][] cost, (int r, int c)[] exits, int r, int c, int spawn) {
    int old = cost[r][c];
    cost[r][c] = 0;                                    // the tower is a wall
    field.Build(cost, exits);
    if (field.Integration[spawn] != int.MaxValue) return true;   // a path exists: place it
    cost[r][c] = old;                                  // the spawn is cut off: refuse
    field.Build(cost, exits);                          // and restore the field without it
    return false;
}
